document.documentElement.classList.add('js');
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#main-nav');
menu?.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(expanded));nav.classList.toggle('is-open',expanded)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){menu.setAttribute('aria-expanded','false');nav.classList.remove('is-open');menu.focus()}});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=filter!=='All'&&card.dataset.category!==filter;if(!card.hidden)count++});document.querySelector('#filter-status').textContent=`Showing ${count} ${filter==='All'?'':filter.toLowerCase()+' '}projects.`}));
const dialog=document.querySelector('#lightbox');
document.querySelectorAll('[data-lightbox]').forEach(a=>a.addEventListener('click',e=>{if(!dialog?.showModal)return;e.preventDefault();dialog.querySelector('img').src=a.href;dialog.querySelector('img').alt=a.querySelector('img').alt;dialog.querySelector('p').textContent=a.dataset.caption;dialog.showModal()}));
dialog?.querySelector('button').addEventListener('click',()=>dialog.close());
dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const form=document.querySelector('#enquiry-form');
if(form){const requested=new URLSearchParams(location.search).get('service')||'';const select=form.elements.service;const name=/bathroom|shower/i.test(requested)?'Bathroom':/installation/i.test(requested)&&/boiler/i.test(requested)?'New boiler':/servicing/i.test(requested)?'Boiler service':/repairs/i.test(requested)&&/boiler/i.test(requested)?'Boiler repair':/heating|radiator/i.test(requested)?'Heating':/plumbing/i.test(requested)?'Plumbing':'';if(name)select.value=name;form.addEventListener('submit',async e=>{e.preventDefault();const endpoint=form.dataset.endpoint,status=document.querySelector('#form-status'),button=form.querySelector('button');if(!endpoint){status.textContent='Online enquiries are not open yet. Please use the available contact options.';return}if(!form.reportValidity())return;button.disabled=true;status.textContent='Sending your enquiry…';try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});if(!response.ok)throw new Error('Request failed');status.textContent='Your enquiry has been sent. Thank you.';form.reset()}catch{status.textContent='Your enquiry could not be sent. Please try again or use a direct contact option.'}finally{button.disabled=false}})}
